try{
    Model\ActiveRecord::setDB($db);session_start();$actor=(int)$db->query("SELECT id FROM usuarios WHERE username='admin_demo'")->fetch_row()[0];$_SESSION=['id'=>$actor,'auth_nivel'=>'contrasena','_auth3b'=>true,'login'=>true];
